import{_ as r,a0 as p,w as n,s as d,ao as l,I as o,x as t,a1 as i,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"如何在 Linux 终端下创建新的文件系统/分区 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 终端下创建新的文件系统/分区 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 终端下创建新的文件系统/分区 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 终端下创建新的文件系统/分区 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151104 How to Create New File Systems or Partitions in the Terminal on Linux","title":"如何在 Linux 终端下创建新的文件系统/分区","tag":"201511","desc":""},"relativePath":"201511/20151104 How to Create New File Systems or Partitions in the Terminal on Linux.md","filePath":"[post].md"}'),m={name:"201511/20151104 How to Create New File Systems or Partitions in the Terminal on Linux.md"};function c(k,e,u,f,w,h){const s=p("Link");return n(),d("div",null,[e[13]||(e[13]=l(`<h1 id="如何在-linux-终端下创建新的文件系统-分区" tabindex="-1">如何在 Linux 终端下创建新的文件系统/分区 <a class="header-anchor" href="#如何在-linux-终端下创建新的文件系统-分区" aria-label="Permalink to “如何在 Linux 终端下创建新的文件系统/分区”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-feature-image.png" alt=""></p><p>在 Linux 中创建分区或新的文件系统通常意味着一件事：安装 Gnome Parted 分区编辑器（GParted）。对于大多数 Linux 用户而言，这是唯一的办法。不过，你是否考虑过在终端创建这些分区和文件系统？当然可以！以下就是方法！</p><h3 id="使用-cfdisk-创建一个基本的-linux-分区" tabindex="-1">使用 CFdisk 创建一个基本的 Linux 分区 <a class="header-anchor" href="#使用-cfdisk-创建一个基本的-linux-分区" aria-label="Permalink to “使用 CFdisk 创建一个基本的 Linux 分区”">​</a></h3><p>以下是如何在命令行中创建一个基本的 Linux 分区的正确方案。要做的第一件事就是先打开你的终端。若你已打开，你需要找到你想要创建分区的磁盘。这可以使用一个简单的命令来找到。</p><pre><code>lsblk
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-lsblk.png" alt="cfdisk-lsblk"></p><p>当你运行了 <code>lsblk</code>，你应该会看到当前系统上每个磁盘的详细列表。看看这个列表，然后找出你想要使用的磁盘。在本文中，我将使用 <code>sdb</code> 来进行演示。</p><p>在终端输入这个命令。它会显示一个功能强大的基于终端的分区编辑程序。</p><pre><code>sudo cfdisk /dev/sdb
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-empty-layout.png" alt="cfdisk-empty-layout"></p><p><strong>注意</strong>: 使用在 <code>lsblk</code> 命令输出的你想要使用的磁盘来替换 <code>sdb</code>。</p><p>当输入此命令后，你将进入分区编辑器中，然后访问你想改变的磁盘。</p><p>由于磁盘分区的不同，这取决于用户的需求，这部分的指南将在 <strong>如何建立一个分离的 Linux home/root 分区布局</strong>。</p><p>首先，需要创建根分区。这需要根据磁盘的字节数来进行分割。我测试的磁盘是 32 GB。</p><p>在 CFdisk 中使用键盘上的方向键选择需要分配的空间。你找到后，请使用箭头键选择 [ NEW ]，然后按 Enter 键。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-create-root-partition.png" alt="cfdisk-create-root-partition"></p><p>该程序会要求你输入分区大小。一旦你指定好大小后，按 Enter 键。这将被称为根分区（或 /dev/sdb1）。</p><p>接下来该创建 home 分区（/dev/sdb2）了。你需要在 CFdisk 中再选择一些空闲分区。使用箭头选择 [ NEW ] 选项，然后按 Enter 键。输入你的 home 分区的大小，然后按 Enter 键来创建它。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-create-home-partition.png" alt="cfdisk-create-home-partition"></p><p>最后，需要创建交换分区。像前两次一样，先找一些空闲分区，并使用箭头选择 [ NEW ] 选项。之后，算下你 Linux 想使用多大的交换分区。</p><p><strong>注意</strong>: 交换分区通常和计算机的内存差不多大。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-specify-partition-type-swap.png" alt="cfdisk-specify-partition-type-swap"></p><p>现在，创建了交换分区，该指定其类型。使用上下箭头来选择它。之后，使用左右箭头选择 [ TYPE ] 。找到 Linux swap 选项，然后按 Enter 键。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-write-partition-table.jpg" alt="cfdisk-write-partition-table"></p><p>所有分区创建后。然后就是将其写入到磁盘。使用右箭头键，选择 [ WRITE ] 选项，然后按 Enter 键。这将直接将新创建的分布写入到磁盘中。</p><h3 id="使用-mkfs-创建文件系统" tabindex="-1">使用 mkfs 创建文件系统 <a class="header-anchor" href="#使用-mkfs-创建文件系统" aria-label="Permalink to “使用 mkfs 创建文件系统”">​</a></h3><p>有时候，你并不需要一个整个重新分区，你只想要创建一个文件系统而已。你可以在终端直接使用 <code>mkfs</code> 命令来实现。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/cfdisk-mkfs-list-partitions-lsblk.png" alt="cfdisk-mkfs-list-partitions-lsblk"></p><p>首先，找出你要使用的磁盘。在终端输入 <code>lsblk</code> 找出来。它会打印出列表，之后只要找到你想创建文件系统的分区或盘符。</p><p>在这个例子中，我将使用第二个硬盘的 <code>/dev/sdb1</code> 作为第一个分区。可以对 <code>/dev/sdb</code> 使用 mkfs（这将会使用整个分区）。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/cfdisk-mkfs-make-file-system-ext4.png" alt="cfdisk-mkfs-make-file-system-ext4"></p><p>要在一个特定的分区上创建新文件系统，只需输入</p><pre><code>sudo mkfs.ext4 /dev/sdb1
</code></pre><p>在终端。应当指出的是，<code>mkfs.ext4</code> 可以换成任何你想要使用的的文件系统。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>虽然使用图形工具编辑文件系统和分区更容易，但终端可以说是更有效的。终端的加载速度更快，点击几个按钮即可。GParted 和其它工具一样，它也是一个完整的工具。我希望在本教程的帮助下，你会明白如何在终端中高效的编辑文件系统。</p><p>你是否更喜欢使用基于终端的方法在 Linux 上编辑分区？不管是不是，请在下面告诉我们。</p><hr>`,39)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),i(s,{href:"https://www.maketecheasier.com/create-file-systems-partitions-terminal-linux/"},{default:a(()=>[...e[0]||(e[0]=[t("https://www.maketecheasier.com/create-file-systems-partitions-terminal-linux/",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=t("作者：",-1)),i(s,{href:"https://www.maketecheasier.com/author/derrikdiener/"},{default:a(()=>[...e[2]||(e[2]=[t("Derrik Diener",-1)])]),_:1}),e[6]||(e[6]=t(" 译者：",-1)),i(s,{href:"https://github.com/strugglingyouth"},{default:a(()=>[...e[3]||(e[3]=[t("strugglingyouth",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const b=r(m,[["render",c]]);export{L as __pageData,b as default};
